// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {LRTDepositPool} from "../src/LRTDepositPool.sol";

contract InvMutTest is Test {
    LRTDepositPool c;
    function setUp() public { c = new LRTDepositPool(); }

    function testFuzz_property(address actor) public {
        // Freshly deployed (never initialized/paused): paused() must report the
        // internal _paused state, which is false. The rule: paused() always
        // reflects the actual pause state (false unless pause() was called).
        vm.prank(actor);
        bool p = c.paused();
        assertTrue(p == false);
    }
}
